/// <summary>
/// CB202_SalesQuotaMinMax
/// </summary>
abstract class METAgreementLineSearchCommitmentType
{
    ItemId                  itemId;
    SalesReceiptDate        receiptDate;
    CustAccount             custAccount;
    InventDim               inventDim;
    SalesUnit               salesUnit;

}

Method.Source:
/// <summary>
/// Construct
/// </summary>
/// <param name = "_commitmentType">Default commitment type</param>
/// <param name = "_agreementLineSearchParameters">The parameters for sales agreement line search.</param>
/// <returns>Instance of class <c>METAgreementLineSearchCommitmentType</c></returns>
static METAgreementLineSearchCommitmentType construct(CommitmentType                   _commitmentType,
                                                      METAgreementLineSearchParameters _agreementLineSearchParameters)
{
    METAgreementLineSearchCommitmentType agreementLineSearchCommitmentType;

    if (!_agreementLineSearchParameters)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    switch (_commitmentType)
    {
        case CommitmentType::ProductQuantity:
            agreementLineSearchCommitmentType = new METAgreementLineSearchCommitmentType_ProductQuantity(_agreementLineSearchParameters);
            break;
        case CommitmentType::ProductVolume:
            agreementLineSearchCommitmentType = new METAgreementLineSearchCommitmentType_ProductVolume(_agreementLineSearchParameters);
            break;
        case CommitmentType::METVendorCategoryProductVolume:
            agreementLineSearchCommitmentType = new METAgreementLineSearchCommitmentType_VendorCategoryProductVolume(_agreementLineSearchParameters);
            break;
        default:
            throw error(strFmt("@SYS19306", funcName()));
    }

    agreementLineSearchCommitmentType.initialise();

    return agreementLineSearchCommitmentType;
}

/// <summary>
/// New method
/// </summary>
/// <param name = "_agreementLineSearchParameters">The parameters for sales agreement line search.</param>
protected void new(METAgreementLineSearchParameters _agreementLineSearchParameters)
{
    itemId          = _agreementLineSearchParameters.getItemId();
    receiptDate     = _agreementLineSearchParameters.getReceiptDate();
    custAccount     = _agreementLineSearchParameters.getCustAccount();
    salesUnit       = _agreementLineSearchParameters.getSalesUnit();
    inventDim       = _agreementLineSearchParameters.getInventDim();

}

/// <summary>
/// Initialise method after new instance of METAgreementLineSearchCommitmentType is created
/// </summary>
protected void initialise()
{

}

/// <summary>
/// Search method
/// </summary>
/// <returns><c>METAgreementLineSearchResult</c> object</returns>
public METAgreementLineSearchResult search()
{    
    METAgreementLineSearchResult result;

    // Search SA line with SO line inventory dimension
    result = this.searchInventDim(inventDim);

    if (!result)
    {
        // Search SA line with blank inventory dimension
        result = this.searchInventDim();
    }

    return result;
}

/// <summary>
/// Search using inventory dimensions or not
/// </summary>
/// <param name = "_inventDim">Inventory dimensions or blank</param>
/// <returns><c>METAgreementLineSearchResult</c> object</returns>
protected METAgreementLineSearchResult searchInventDim(InventDim _inventDim = null)
{
    METAgreementLineSearchResult    result;        
    SalesAgreementHeader            salesAgreementHeader;
    AgreementLine                   agreementLine;
    AgreementClassification         agreementClassification;

    // Build query
    QueryRun qr;

    // Search SA line with SO line inventory dimension
    qr = new QueryRun(this.buildQuery(_inventDim));

    while (qr.next())
    {
        agreementLine = qr.get(tableNum(AgreementLine));
        salesAgreementHeader = qr.get(tableNum(SalesAgreementHeader));
        agreementClassification = qr.get(tableNum(AgreementClassification));

        if (this.validateAgreementLine(agreementLine))
        {
            return METAgreementLineSearchResult::contruct(salesAgreementHeader, agreementLine, agreementClassification);
        }
    }

    return result;
}

/// <summary>
/// Build the query to find the SA line
/// </summary>
/// <param name = "_inventDim">SO line inventory dimension</param>
/// <returns><c>Query</c> object</returns>
private Query buildQuery(InventDim _inventDim = null)
{
    QueryBuildRange qbr;
    Query query = new Query();
    QueryBuildDataSource agreementLineQbds, salesAgreementHeaderQbds, agreementClassificationQbds, inventDimQbds;

    agreementLineQbds = query.addDataSource(tableNum(AgreementLine));        

    agreementLineQbds.addRange(fieldNum(AgreementLine, EffectiveDate)).value(SysQueryRangeUtil::metLessThanEqualDate(receiptDate));
    agreementLineQbds.addRange(fieldNum(AgreementLine, ExpirationDate)).value(SysQueryRangeUtil::metGreaterThanEqualDate(receiptDate));
    // SG 266541
    // Do not filter by itemId for vendor category value commitment as we will have to check if the product is under a node from the sales category field
    this.agreementLineAddRange(agreementLineQbds);

    salesAgreementHeaderQbds = agreementLineQbds.addDataSource(tableNum(SalesAgreementHeader));
    salesAgreementHeaderQbds.relations(true);
    salesAgreementHeaderQbds.addRange(fieldNum(SalesAgreementHeader, AgreementState)).value(queryValue(AgreementState::Effective));
    salesAgreementHeaderQbds.addRange(fieldNum(SalesAgreementHeader, CustAccount)).value(queryValue(custAccount));
    salesAgreementHeaderQbds.addRange(fieldNum(SalesAgreementHeader, DefaultAgreementLineType)).value(queryValue(this.getCommitmentType()));             

    agreementClassificationQbds = salesAgreementHeaderQbds.addDataSource(tableNum(AgreementClassification));
    agreementClassificationQbds.relations(true);

    if (_inventDim)
    {
        const str inventDimIdRange = '(%1.INVENTDIMID == %2.INVENTDIMID)';
        inventDimQbds = agreementClassificationQbds.addDataSource(tableNum(InventDim));
        inventDimQbds.joinMode(JoinMode::ExistsJoin);
        qbr = inventDimQbds.addRange(fieldNum(InventDim, InventDimId));
        qbr.value(strFmt(inventDimIdRange, inventDimQbds.name(), agreementLineQbds.name()));
        inventDimQbds.addRange(fieldNum(InventDim, InventSiteId)).value(queryValue(_inventDim.InventSiteId));
        inventDimQbds.addRange(fieldNum(InventDim, InventLocationId)).value(queryValue(_inventDim.InventLocationId));
    }
    else
    {
        agreementLineQbds.addRange(fieldNum(AgreementLine, InventDimId)).value(queryValue(InventDim::inventDimIdBlank()));
    }

    return query;
}

/// <summary>
/// Add additional ranges to the agreement line query build data source
/// </summary>
/// <param name = "_agreementLineQbds">Agreement line query build data source</param>
protected void agreementLineAddRange(QueryBuildDataSource _agreementLineQbds)
{
    _agreementLineQbds.addRange(fieldNum(AgreementLine, ItemId)).value(queryValue(itemId));
}

/// <summary>
/// Validate the found agreement line
/// </summary>
/// <param name = "_agreementLine"><c>AgreementLine</c> record</param>
/// <returns>Boolean if valid; otherwise, false.</returns>
protected boolean validateAgreementLine(AgreementLine _agreementLine)
{
    return true;
}

/// <summary>
/// Abstract method to get the commitment type
/// </summary>
/// <returns><c>CommitmentType</c></returns>
abstract protected CommitmentType getCommitmentType()
{

}
